    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Sports(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static object Get(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static void Set(object owner,string name,object value){if(owner.GetType().GetField(name,Any) is FieldInfo field)field.SetValue(owner,value);else owner.GetType().GetProperty(name,Any).SetValue(owner,value);}
    static object Call(object owner,string name,params object[] args)=>owner.GetType().GetMethods(Any).Single(method=>method.Name==name&&method.GetParameters().Length==args.Length).Invoke(owner,args);
    static object Registry(string name,params object[] args)=>Sports("SportsParticipantRegistry").GetMethod(name).Invoke(null,args);
    Component match;IDisposable lease;GameObject isolation;bool limbo;Component[] trucks;object[] hosts;string[] ids;
    [TearDown]public void Cleanup(){Time.timeScale=1;if(match!=null)Call(match,"SetupScreen");if(isolation!=null)UnityEngine.Object.DestroyImmediate(isolation);Registry("ForgetCache");lease?.Dispose();lease=null;}
    static void Save(string id,string body){var draft=Registry("GetAppearance",id);Set(draft,"bodyId",body);((IList)Get(draft,"selections")).Clear();Registry("TrySetAppearance",id,draft);Registry("ForgetCache");Assert.That(Get(Registry("GetAppearance",id),"bodyId"),Is.EqualTo(body));}
    IEnumerator Load(bool limboSport)
    {
        limbo=limboSport;lease=(IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"LimboKickAppearance"+Guid.NewGuid().ToString("N")});Registry("ForgetCache");isolation=new GameObject("Saved Limbo Kickball appearance fixture");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Sports("SportsProbeInputIsolation"));string mode=limbo?"TruckLimbo":"TruckKickball";EditorSceneManager.LoadSceneInPlayMode("Assets/"+mode+"/Scenes/"+mode+".unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;
        match=(Component)UnityEngine.Object.FindAnyObjectByType(Type.GetType(limbo?"LWS.TruckLimbo.LimboMatch, Assembly-CSharp":"LWS.TruckKickball.KickballMatch, Assembly-CSharp",true));Assert.That(match,Is.Not.Null);Call(match,"AllBots");if(!limbo){Set(match,"teamA",6);Set(match,"teamB",6);}Set(Get(match,"setup"),"count",limbo?8:12);Call(match,"NormalizeSetup");trucks=((Array)Get(match,limbo?"racers":"agents")).Cast<object>().Select(r=>(Component)Get(r,"truck")).ToArray();hosts=((Array)Get(match,limbo?"limboAppearanceHosts":"appearanceHosts")).Cast<object>().ToArray();Assert.That(hosts.Length,Is.EqualTo(limbo?8:12),"Run BindMissingLimboAndKickballHosts first.");if(limbo)Assert.That(((Array)Get(match,"appearanceHosts")),Is.Empty,"Limbo composes only after original standing suspension reset.");ids=new string[hosts.Length];for(int i=0;i<hosts.Length;i++){ids[i]=(string)Get(Registry("Create","Same Clearance Driver"),"id");Registry("UseInSeat",i,ids[i]);Save(ids[i],i%2==0?"truck.fire":"novelty.icecream");Assert.That(((Component)hosts[i]).transform,Is.SameAs(trucks[i].transform));Assert.That(Get(hosts[i],"participantSlot"),Is.EqualTo(i));}Call(match,"RefreshParticipants",false);
    }
    IEnumerable<Component> Physical()=>trucks.SelectMany(t=>t.GetComponentsInChildren<Component>(true)).Where(c=>c is Rigidbody||c is Collider).Distinct();
    static string Config(Component c){if(c is Rigidbody b)return b.mass+"/"+b.centerOfMass.ToString("R")+"/"+b.inertiaTensor.ToString("R")+"/"+b.linearDamping+"/"+b.angularDamping+"/"+b.constraints;var shape=(Collider)c;string s=shape.isTrigger+"/"+shape.contactOffset+"/"+(shape.sharedMaterial!=null?shape.sharedMaterial.GetInstanceID():0);if(shape is BoxCollider box)s+="/"+box.center.ToString("R")+"/"+box.size.ToString("R");if(shape is MeshCollider mesh)s+="/"+(mesh.sharedMesh!=null?mesh.sharedMesh.GetInstanceID():0)+"/"+mesh.convex;return s;}
    Dictionary<Component,string> Snapshot()=>Physical().ToDictionary(c=>c,Config);
    void Same(Dictionary<Component,string> before){CollectionAssert.AreEquivalent(before.Keys,Physical());foreach(var pair in before)Assert.That(Config(pair.Key),Is.EqualTo(pair.Value),"Composition changed existing physical configuration: "+pair.Key.name);}
    string Wheels()=>string.Join(";",trucks.SelectMany(t=>((Array)Get(t,"wheels")).Cast<object>()).Select(w=>((Component)w).GetInstanceID()+"/"+Get(Get(w,"wheel"),"radius")+"/"+Get(Get(w,"wheel"),"width")+"/"+Get(Get(w,"spring"),"maxLength")+"/"+Get(Get(w,"spring"),"maxForce")));
    IEnumerator OriginalStartup()
    {
        string field=limbo?"limboAppearanceHosts":"appearanceHosts";var bindings=(Array)Get(match,field);var truckBindings=trucks.Select(t=>Get(t,"appearanceHost")).ToArray();Set(match,field,Array.CreateInstance(Sports("SportsTruckAppearanceHost"),0));foreach(var truck in trucks)Set(truck,"appearanceHost",null);
        try{Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));if(limbo){double deadline=Time.realtimeSinceStartupAsDouble+8;while(Time.realtimeSinceStartupAsDouble<deadline&&Get(match,"Phase").ToString()!="Attempt")yield return null;Assert.That(Get(match,"Phase").ToString(),Is.EqualTo("Attempt"));}yield return null;yield return null;}
        finally{Set(match,field,bindings);for(int i=0;i<trucks.Length;i++)Set(trucks[i],"appearanceHost",truckBindings[i]);}
        ((Behaviour)match).enabled=false;foreach(var truck in trucks){Call(truck,"Power",false);((Rigidbody)Get(truck,"body")).isKinematic=true;}yield return null;
    }
    static string Relative(Transform part,Transform root){string path=part.name;while(part.parent!=root){part=part.parent;Assert.That(part,Is.Not.Null);path=part.name+"/"+path;}return path;}
    void AssertArt(string first)
    {
        for(int i=0;i<hosts.Length;i++){Assert.That(Get(hosts[i],"ProfileId"),Is.EqualTo(ids[i]));Assert.That(Get(hosts[i],"EffectiveBodyId"),Is.EqualTo(i==0?first:i%2==0?"truck.fire":"novelty.icecream"));var model=(Transform)Get(hosts[i],"AppearanceRoot");Assert.That(model,Is.Not.Null);Assert.That(float.IsFinite(model.lossyScale.x)&&model.lossyScale.x>0,Is.True);Assert.That(model.GetComponentsInChildren<Collider>(true),Is.Empty);Assert.That(model.GetComponentsInChildren<Rigidbody>(true),Is.Empty);Assert.That(((Renderer[])Get(hosts[i],"originalBodyRenderers")).Length,Is.EqualTo(29));Assert.That(((Renderer[])Get(hosts[i],"originalBodyRenderers")).All(r=>!r.enabled),Is.True);var entry=Call(Get(hosts[i],"catalog"),"FindBody",Get(hosts[i],"EffectiveBodyId"));var expected=((GameObject)Get(entry,"visualPrefab")).GetComponentsInChildren<Renderer>(true);var actual=(Renderer[])Get(hosts[i],"paintRenderers");Assert.That(actual.Length,Is.EqualTo(expected.Length));for(int r=0;r<actual.Length;r++)CollectionAssert.AreEqual(expected[r].sharedMaterials,actual[r].sharedMaterials);}
    }
    void SameGhostPaint(object replay,int[] indices)
    {
        var sources=(Transform[])Get(replay,"sources");var ghosts=(Transform[])Get(replay,"ghosts");for(int i=0;i<hosts.Length;i++)foreach(var slot in (Array)Get(hosts[i],"paintSlots")){var renderer=((Renderer[])Get(hosts[i],"paintRenderers"))[(int)Get(slot,"rendererIndex")];var copy=ghosts[indices[i]].Find(Relative(renderer.transform,sources[indices[i]])).GetComponent<Renderer>();int index=(int)Get(slot,"materialIndex");CollectionAssert.AreEqual(renderer.sharedMaterials,copy.sharedMaterials);var a=new MaterialPropertyBlock();var b=new MaterialPropertyBlock();renderer.GetPropertyBlock(a,index);copy.GetPropertyBlock(b,index);Assert.That(b.GetColor("_BaseColor"),Is.EqualTo(a.GetColor("_BaseColor")));}
    }
    IEnumerator Exercise(bool limboSport)
    {
        yield return Load(limboSport);var originalRefs=Physical().ToArray();var actors=((Array)Get(match,limbo?"racers":"agents")).Cast<object>().ToArray();var review=limbo?Get(match,"review"):null;var replay=limbo?Get(review,"motion"):Get(match,"replay");var sources=((Transform[])Get(replay,"sources")).ToArray();var ghosts=((Transform[])Get(replay,"ghosts")).ToArray();Assert.That(sources.Length,Is.EqualTo(limbo?16:13));var indices=Enumerable.Range(0,hosts.Length).Select(i=>limbo?i*2:i).ToArray();for(int i=0;i<hosts.Length;i++)Assert.That(sources[indices[i]],Is.SameAs(limbo?trucks[i].transform:Get(trucks[i],"visuals")));var untouched=Enumerable.Range(0,sources.Length).Where(i=>!indices.Contains(i)).ToArray();var unmodifiedParts=untouched.SelectMany(i=>ghosts[i].GetComponentsInChildren<Transform>(true)).ToArray();var equipment=hosts.SelectMany(h=>(Transform[])Get(h,"protectedRoots")).Distinct().ToArray();yield return OriginalStartup();var equipmentPhysical=equipment.SelectMany(t=>t.GetComponentsInChildren<Component>(true)).Where(c=>c is Collider||c is Rigidbody).Distinct().ToDictionary(c=>c,Config);foreach(var part in originalRefs)Assert.That(Physical().Contains(part),Is.True);
        foreach(string body in new[]{"truck.fire","truck.monster","truck.lifted","semi.lowrider","novelty.hotdog","novelty.icecream","semi.standard"})
        {
            Save(ids[0],body);Call(match,"RefreshParticipants",false);
            if(limbo)
            {
                // Exercise the original compression authority before requesting
                // the changed body; BeginRound must restore it before composing.
                Call(actors[0],"Prepare",true,(float)Get(Get(match,"rules"),"Height"));Call(actors[0],"Release");Call(actors[0],"Step",new Vector2(.25f,.1f),true,.2f);Assert.That((float)Get(actors[0],"Compression"),Is.GreaterThan(0));Call(match,"BeginRound");Assert.That(Get(actors[0],"Compression"),Is.EqualTo(0f));foreach(var wheel in (Array)Get(trucks[0],"wheels"))Assert.That(Get(Get(wheel,"spring"),"maxLength"),Is.EqualTo(Get(actors[0],"standingTravel")));
                var physical=Snapshot();var hull=Call(actors[0],"Hull");var wheelConfig=Wheels();for(int i=0;i<hosts.Length;i++)Assert.That(Call(hosts[i],"Prepare",ids[i],Get(((Array)Get(Get(match,"setup"),"players")).GetValue(i),"color")),Is.EqualTo(true));Same(physical);Assert.That(Call(actors[0],"Hull"),Is.EqualTo(hull));Assert.That(Wheels(),Is.EqualTo(wheelConfig));
                for(int i=0;i<hosts.Length;i++)foreach(var fit in (Array)Get(hosts[i],"compatibleBodies"))foreach(var group in (Array)Get(fit,"wheelGeometry"))Assert.That(Get(group,"visualDiameter"),Is.EqualTo((float)Get(Get(((Array)Get(trucks[i],"wheels")).GetValue((int)Get(group,"physicalWheel")),"wheel"),"radius")*2));
                Call(review,"Record",0f);Call(review,"Record",.2f);
            }
            else
            {
                var physical=Snapshot();string wheels=Wheels();var gearState=equipment.Select(t=>(t.localPosition,t.localRotation,t.localScale,t.gameObject.activeSelf)).ToArray();Call(match,"PrepareAppearances");Same(physical);Assert.That(Wheels(),Is.EqualTo(wheels));CollectionAssert.AreEqual(gearState,equipment.Select(t=>(t.localPosition,t.localRotation,t.localScale,t.gameObject.activeSelf)));foreach(var pair in equipmentPhysical)Assert.That(Config(pair.Key),Is.EqualTo(pair.Value));Call(match,"PreparePlate",false);Call(match,"CaptureAppearanceReplay",0f,8191);Call(match,"CaptureAppearanceReplay",.2f,8191);
                for(int i=0;i<hosts.Length;i++){var marker=(Renderer)Get(actors[i],"teamMarker");var replayMarker=(Renderer)Get(actors[i],"replayTeamMarker");Assert.That(marker.enabled,Is.True);Assert.That(replayMarker,Is.SameAs(ghosts[i].Find(Relative(marker.transform,sources[i])).GetComponent<Renderer>()));Assert.That(replayMarker.sharedMaterial,Is.SameAs(marker.sharedMaterial));Assert.That(ghosts[i].GetComponentsInChildren<Transform>(true).Any(t=>t.name==((Transform)Get(actors[i],"catchingCup")).name),Is.False,"Retain original inner-model replay root; do not silently migrate physical cup authority.");}
            }
            AssertArt(body);SameGhostPaint(replay,indices);CollectionAssert.AreEqual(sources,(Transform[])Get(replay,"sources"));CollectionAssert.AreEqual(ghosts,(Transform[])Get(replay,"ghosts"));CollectionAssert.AreEqual(unmodifiedParts,untouched.SelectMany(i=>ghosts[i].GetComponentsInChildren<Transform>(true)));
        }
        var buffers=Get(replay,"roots");if(limbo){Call(match,"BeginRound");Call(review,"Record",0f);Call(review,"Record",.2f);}else{Call(match,"PreparePlate",false);Call(match,"CaptureAppearanceReplay",0f,8191);Call(match,"CaptureAppearanceReplay",.2f,8191);}Assert.That(Get(replay,"roots"),Is.SameAs(buffers));Call(replay,"Begin",0f,float.PositiveInfinity);Assert.That(Get(replay,"Playing"),Is.EqualTo(true));Assert.That(Call(replay,"RefreshAppearanceSources",indices,true),Is.EqualTo(false));Call(replay,"End");
        if(limbo)
        {
            var catalog=Get(hosts[0],"catalog");var hat=((Array)Get(catalog,"cosmetics")).Cast<object>().First(item=>(string)Get(item,"slotId")=="hat");var draft=Registry("GetAppearance",ids[0]);var selection=Activator.CreateInstance(Sports("SportsTruckCosmeticSelection"));Set(selection,"slotId","hat");Set(selection,"itemId",Get(hat,"id"));((IList)Get(draft,"selections")).Add(selection);Registry("TrySetAppearance",ids[0],draft);string saved=JsonUtility.ToJson(Registry("GetAppearance",ids[0]));int revision=(int)Get(hosts[0],"AppearanceRevision");var report=Call(hosts[0],"EvaluateDraft",draft);CollectionAssert.Contains((string[])Get(report,"unavailableSlots"),"hat");Assert.That(Get(hosts[0],"AppearanceRevision"),Is.EqualTo(revision));Call(match,"BeginRound");Assert.That(JsonUtility.ToJson(Registry("GetAppearance",ids[0])),Is.EqualTo(saved));Assert.That(((Transform)Get(hosts[0],"AppearanceRoot")).GetComponentsInChildren(Sports("SportsTruckAppearanceMountTag"),true).Cast<Component>().Any(t=>(string)Get(t,"slotId")=="hat"),Is.False);
            Call(review,"Record",0f);Call(review,"Record",.2f);Call(match,"EndMatch");Assert.That(Get(match,"Finished"),Is.EqualTo(true),"Use the actual Session result/StopGame lifecycle before reviewing recorded poses.");var live=trucks.SelectMany(t=>t.GetComponentsInChildren<Renderer>(true)).ToArray();var prior=live.Select(r=>r.forceRenderingOff).ToArray();Assert.That(Call(review,"Play"),Is.EqualTo(true));Call(review,"Stop",false);CollectionAssert.AreEqual(prior,live.Select(r=>r.forceRenderingOff));
        }
        else
        {
            var presentation=Get(match,"presentation");var player=((Array)Get(Get(match,"setup"),"players")).GetValue(0);Set(player,"source",Enum.Parse(Get(player,"source").GetType(),"Keyboard"));Set(match,"ViewMode",2);Call(presentation,"Layout");var cabs=((Array)Get(presentation,"appearanceCabs")).Cast<object>().ToArray();Assert.That(Get(cabs[0],"assignedOwner"),Is.SameAs(hosts[0]));var camera=(Camera)Get(((Array)Get(Get(match,"views"),"views")).GetValue(0),"view");var teamMarker=(Renderer)Get(actors[0],"teamMarker");var chosen=((Transform)Get(hosts[0],"AppearanceRoot")).GetComponentsInChildren<Renderer>(true).First(r=>r.enabled);Assert.That(chosen,Is.Not.SameAs(teamMarker));Assert.That(teamMarker.forceRenderingOff,Is.False,"Original team band starts unhidden before the explicit owned-camera callback.");chosen.forceRenderingOff=true;var cup=(Transform)Get(actors[0],"catchingCup");var cupStates=cup.GetComponentsInChildren<Renderer>(true).Select(r=>r.forceRenderingOff).ToArray();Call(presentation,"BeginCamera",default(UnityEngine.Rendering.ScriptableRenderContext),camera);Assert.That(((Renderer[])Get(hosts[0],"ExteriorRenderers")).All(r=>r.forceRenderingOff),Is.True);CollectionAssert.AreEqual(cupStates,cup.GetComponentsInChildren<Renderer>(true).Select(r=>r.forceRenderingOff));Call(presentation,"RefreshAppearanceExteriors");Assert.That(chosen.forceRenderingOff,Is.True,"Refresh must restore the original per-camera hiding flags before discarding cache.");Assert.That(teamMarker.forceRenderingOff,Is.False,"Restore must preserve the independent original team band prior flag.");var restored=((Renderer[])Get(hosts[0],"ExteriorRenderers")).Select(r=>r.forceRenderingOff).ToArray();var wrongCamera=(Camera)Get(Get(Get(match,"views"),"broadcast"),"view");Assert.That(wrongCamera,Is.Not.SameAs(camera));Call(presentation,"BeginCamera",default(UnityEngine.Rendering.ScriptableRenderContext),wrongCamera);CollectionAssert.AreEqual(restored,((Renderer[])Get(hosts[0],"ExteriorRenderers")).Select(r=>r.forceRenderingOff),"An unrelated camera must not acquire the owner exterior cache.");chosen.forceRenderingOff=false;Set(player,"source",Enum.Parse(Get(player,"source").GetType(),"AI"));
        }
        int finalRevision=(int)Get(hosts[0],"AppearanceRevision");Call(match,"SetupScreen");Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));Assert.That(Get(hosts[0],"AppearanceRevision"),Is.EqualTo(finalRevision));AssertArt("semi.standard");TestContext.WriteLine("LIMBO_KICK_APPEARANCE "+(limbo?"Limbo":"Kickball")+" actual saved owners/all7 bodies, explicit original truck/bar/ball replay roots and untouched ghost branches, original initialized physical envelopes/springs, paint/material/gear/cache refs, same-body buffers, playing guard/rematch. Limbo genuine compression reset + reserved hat preference persistence; Kickball actual cab temporary hiding/cradle isolation. Controlled fixture, not full match/art/hardware acceptance.");
    }
    [UnityTest,Timeout(180000)]public IEnumerator LimboEightBodiesRetainActualCompressionClearanceAndInterleavedPhysicalBars(){yield return Exercise(true);}
    [UnityTest,Timeout(180000)]public IEnumerator KickballTwelveBodiesPreserveCradlesTeamBandsCabHidingAndThirteenthBallReplay(){yield return Exercise(false);}
